import sys
import csv
import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit.circuit.library import StatePreparation
from qiskit.quantum_info import Statevector
from qiskit_aer import AerSimulator

# ---- Inference settings baked in from training (do not modify) ---------------
N_QUBITS        = 4
N_FEAT          = 12
N_DIM           = 16
USE_STATEVECTOR = True   # True = exact statevector; False = shot-based
Nm              = 1000                # shots per call (used when USE_STATEVECTOR=False and IBM=None)

# ---- IBM Quantum backend (name baked in; credentials NOT stored here) --------
# If training used IBM hardware, IBM_BACKEND holds the backend name.
# Set IBM_TOKEN below to run inference on that hardware; leave as None for local simulation.
IBM_BACKEND = None
IBM_TOKEN   = None   # <-- fill in your IBM Quantum API token if you want to use IBM hardware

# ---- Trained parameters (baked in as literals inside the circuit below) ------
THETA_FINAL  = [-0.12314950021800596, 2.898994227722365, -2.1934909846109223, 3.0382006865428046, -1.1879865467596282, -0.19206297199230657, 2.4238594810834395, -0.6127403435748365, 0.8076311434977127, -2.865342305936455, 1.6537309289399231, 0.9659863344676802, -0.3806529533185009, 1.6859710447537823, -1.3940306673942264, -0.2800647435629138, -2.132646288300059, 0.30586070657156544, -1.9809984806967318, -1.6470948877117577, 1.438443665267323, -1.3797324654618157, -0.09304785175906581, 3.0205609103866915, 2.9006776963489322, 1.4123968531268782, 0.259035973033601, -1.4018339086482767]
THETA_LABELS = ['RX(q0) = -0.123150 rad', 'RZ(q0) = 2.898994 rad', 'RX(q1) = -2.193491 rad', 'RZ(q1) = 3.038201 rad', 'RX(q2) = -1.187987 rad', 'RZ(q2) = -0.192063 rad', 'RX(q3) = 2.423859 rad', 'RZ(q3) = -0.612740 rad', 'CTRL-RX(ctrl=q3, tgt=q2) = 0.807631 rad', 'CTRL-RX(ctrl=q3, tgt=q1) = -2.865342 rad', 'CTRL-RX(ctrl=q3, tgt=q0) = 1.653731 rad', 'CTRL-RX(ctrl=q2, tgt=q3) = 0.965986 rad', 'CTRL-RX(ctrl=q2, tgt=q1) = -0.380653 rad', 'CTRL-RX(ctrl=q2, tgt=q0) = 1.685971 rad', 'CTRL-RX(ctrl=q1, tgt=q3) = -1.394031 rad', 'CTRL-RX(ctrl=q1, tgt=q2) = -0.280065 rad', 'CTRL-RX(ctrl=q1, tgt=q0) = -2.132646 rad', 'CTRL-RX(ctrl=q0, tgt=q3) = 0.305861 rad', 'CTRL-RX(ctrl=q0, tgt=q2) = -1.980998 rad', 'CTRL-RX(ctrl=q0, tgt=q1) = -1.647095 rad', 'RX(q0) = 1.438444 rad', 'RZ(q0) = -1.379732 rad', 'RX(q1) = -0.093048 rad', 'RZ(q1) = 3.020561 rad', 'RX(q2) = 2.900678 rad', 'RZ(q2) = 1.412397 rad', 'RX(q3) = 0.259036 rad', 'RZ(q3) = -1.401834 rad']

# ---- Feature standardisation from training (do not modify) -------------------
# z-score with the mean/std of the TRAINING events; None = no standardisation.
FEATURE_MEAN = None
FEATURE_STD  = None

# Warn if the classifier was trained on IBM hardware but no token is provided.
if IBM_BACKEND is not None and IBM_TOKEN is None:
    print(f"Warning: this classifier was trained on IBM hardware ({IBM_BACKEND}).")
    print( "         IBM_TOKEN is None — running with local AerSimulator instead.")
    print( "         Set IBM_TOKEN above to run inference on the original hardware.")

def preprocess(x_raw):
    # Standardise with the training mean/std (if used in training), then
    # zero-pad 12 features to 16 dimensions and normalise to unit L2 norm.
    x = np.asarray(x_raw, dtype=float)
    if FEATURE_MEAN is not None:
        x = (x - np.asarray(FEATURE_MEAN)) / np.asarray(FEATURE_STD)
    x_padded = np.concatenate([x, np.zeros(N_DIM - N_FEAT)])
    norm = np.linalg.norm(x_padded)
    if norm < 1e-12:
        raise ValueError("Zero-norm feature vector — cannot embed.")
    return x_padded / norm

def classify(features):
    # Build the full PQC for one event: amplitude embedding + variational form.
    # The trained rotation angles are baked into the gate lines below as literals.
    amplitudes = preprocess(features)
    qc = QuantumCircuit(N_QUBITS)
    qc.append(StatePreparation(amplitudes.tolist(), normalize=False), range(N_QUBITS))
    qc.rx(-0.1231495002, 0)
    qc.rz(2.8989942277, 0)
    qc.rx(-2.1934909846, 1)
    qc.rz(3.0382006865, 1)
    qc.rx(-1.1879865468, 2)
    qc.rz(-0.1920629720, 2)
    qc.rx(2.4238594811, 3)
    qc.rz(-0.6127403436, 3)
    qc.crx(0.8076311435, 3, 2)
    qc.crx(-2.8653423059, 3, 1)
    qc.crx(1.6537309289, 3, 0)
    qc.crx(0.9659863345, 2, 3)
    qc.crx(-0.3806529533, 2, 1)
    qc.crx(1.6859710448, 2, 0)
    qc.crx(-1.3940306674, 1, 3)
    qc.crx(-0.2800647436, 1, 2)
    qc.crx(-2.1326462883, 1, 0)
    qc.crx(0.3058607066, 0, 3)
    qc.crx(-1.9809984807, 0, 2)
    qc.crx(-1.6470948877, 0, 1)
    qc.rx(1.4384436653, 0)
    qc.rz(-1.3797324655, 0)
    qc.rx(-0.0930478518, 1)
    qc.rz(3.0205609104, 1)
    qc.rx(2.9006776963, 2)
    qc.rz(1.4123968531, 2)
    qc.rx(0.2590359730, 3)
    qc.rz(-1.4018339086, 3)
    # Evaluate P(qubit 0 = |1>) using the same method as training.
    if IBM_BACKEND is not None and IBM_TOKEN is not None:
        # Run on real IBM Quantum hardware using the backend used during training.
        from qiskit_ibm_runtime import QiskitRuntimeService, SamplerV2
        service    = QiskitRuntimeService(channel="ibm_quantum", token=IBM_TOKEN)
        hw_backend = service.backend(IBM_BACKEND)
        qc.measure_all()
        qc_t       = transpile(qc, hw_backend)
        with SamplerV2(backend=hw_backend) as sampler:
            result = sampler.run([qc_t], shots=Nm).result()
        counts = result[0].data.meas.get_counts()
        total  = sum(counts.values())
        return float(sum(v for k, v in counts.items() if k[-1] == '1') / total)
    elif USE_STATEVECTOR:
        # Exact evaluation — same as training when USE_STATEVECTOR=True.
        return float(Statevector.from_instruction(qc).probabilities([0])[1])
    else:
        # Shot-based local simulation — same as training when USE_STATEVECTOR=False.
        qc.measure_all()
        backend = AerSimulator()
        counts  = backend.run(transpile(qc, backend), shots=Nm).result().get_counts()
        total   = sum(counts.values())
        return float(sum(v for k, v in counts.items() if k[-1] == '1') / total)

def print_result(y, index=None):
    # Print one result line: probability and SIGNAL/BACKGROUND label.
    prefix = f"Event {index:6d} : " if index is not None else ""
    label  = "SIGNAL" if y >= 0.5 else "BACKGROUND"
    print(f"{prefix}P(signal) = {y:.4f}   ->   {label}")

if len(sys.argv) > 1:
    # Mode 2: read a CSV file and classify every event in it.
    # Expected CSV format: col 0-11 = 12 features; col 12+ ignored (same as training data).
    with open(sys.argv[1], newline='') as f:
        reader = csv.reader(f)
        for i, row in enumerate(reader):
            if not row or row[0].startswith('#'):
                continue   # skip blank lines and comment lines
            print_result(classify([float(x) for x in row[:N_FEAT]]), index=i)
else:
    # Mode 1: classify a single event — replace your_event_features with real values.
    your_event_features = [1.0] * N_FEAT   # <-- replace with your 12 feature values
    print_result(classify(your_event_features))
